format_code:
/* LED blink via state machine */

hardware {
    pin led = 2
}

machine blinker {
    state off_state {
        enter {
            led.off()
        }
        after 500ms -> on_state
    }
    state on_state {
        enter {
            led.on()
        }
        after 500ms -> off_state
    }
}

system_graph.mermaid:
flowchart LR
    u_blinker[["blinker"]]
    p_led(["led"])
    u_blinker -->|off, on| p_led
